<?php
require_once __DIR__.'/../includes/auth.php';require_login();require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$target=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);if($target&&$target!==current_user_id()){if($action==='toggle_status')$pdo->prepare("UPDATE users SET status=IF(status='active','blocked','active') WHERE user_id=? AND role<>'admin'")->execute([$target]);elseif($action==='promote')$pdo->prepare("UPDATE users SET role='admin' WHERE user_id=?")->execute([$target]);elseif($action==='demote')$pdo->prepare("UPDATE users SET role='user' WHERE user_id=?")->execute([$target]);}header('Location: index.php');exit;}
$stats=[];foreach(['users'=>'SELECT COUNT(*) FROM users','active_users'=>"SELECT COUNT(*) FROM users WHERE status='active'",'conversations'=>'SELECT COUNT(*) FROM conversations','messages'=>'SELECT COUNT(*) FROM messages','groups'=>"SELECT COUNT(*) FROM conversations WHERE conversation_type='group'"] as $k=>$q){$stats[$k]=(int)$pdo->query($q)->fetchColumn();}$users=$pdo->query("SELECT user_id,full_name,username,email,role,status,created_at,last_seen FROM users ORDER BY created_at DESC LIMIT 200")->fetchAll();$pageTitle='Admin dashboard';require __DIR__.'/../includes/header.php';?>
<section class="admin-page"><div class="dashboard-heading"><div><div class="eyebrow">SYSTEM MANAGEMENT</div><h1>Admin dashboard<span class="heading-dot">.</span></h1><p class="muted">Review activity and manage ChatApp accounts.</p></div><a class="button button-ghost" href="../dashboard.php">← Return to app</a></div><div class="stats-grid"><?php foreach(['users'=>'Total users','active_users'=>'Active users','conversations'=>'Conversations','messages'=>'Messages','groups'=>'Groups'] as $k=>$label): ?><div class="stat-card"><small><?= e($label) ?></small><strong><?= number_format($stats[$k]) ?></strong></div><?php endforeach; ?></div><section class="panel admin-users"><div class="panel-heading"><h2>User management</h2><span class="count-pill">Latest 200</span></div><div class="table-scroll"><table class="admin-table"><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['full_name']) ?></strong><small>@<?= e($u['username']) ?></small></td><td><?= e($u['email']) ?></td><td><?= e($u['role']) ?></td><td><span class="status-pill <?= e($u['status']) ?>"><?= e($u['status']) ?></span></td><td><?= e(date('d M Y',strtotime($u['created_at']))) ?></td><td><?php if((int)$u['user_id']!==current_user_id()): ?><div class="admin-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$u['user_id'] ?>"><input type="hidden" name="action" value="toggle_status"><button class="button button-ghost button-small" type="submit"><?= $u['status']==='active'?'Block':'Unblock' ?></button></form><?php if($u['role']==='admin'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$u['user_id'] ?>"><input type="hidden" name="action" value="demote"><button class="button button-ghost button-small" type="submit">Remove admin</button></form><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$u['user_id'] ?>"><input type="hidden" name="action" value="promote"><button class="button button-ghost button-small" type="submit">Make admin</button></form><?php endif; ?></div><?php else: ?><small>Current account</small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><p class="muted small-text">For this college demo, block status prevents login. Use administrator permissions responsibly.</p></section><?php require __DIR__.'/../includes/footer.php';?>
